-- issue #69「パスワードを忘れたら」機能の本番反映(issue #72の本番DB更新の仕組みによる最初のマイグレーション)。
-- 「V1」はFlyway導入時点(本番相当環境の既存スキーマ)を表すベースラインのため、実体を持たない。
-- 本ファイルは、ACCNT.MAIL_ADDRESSへのユニーク制約追加、PASSWORD_RESETテーブルの新設、
-- 及び画面定義・エラーメッセージ等のマスタデータ追加を行う。

-- ACCNT.MAIL_ADDRESSにユニーク制約を追加する。
-- SQLiteは既存カラムへのUNIQUE制約追加(ALTER TABLE ADD CONSTRAINT)に対応していないため、
-- 実質的に同義であるUNIQUE INDEXの作成で代替する(MySQL移行後も同様に動作する)。
CREATE UNIQUE INDEX IF NOT EXISTS UX_ACCNT_MAIL_ADDRESS ON ACCNT (MAIL_ADDRESS);

-- PASSWORD_RESETテーブルを新設する。
CREATE TABLE IF NOT EXISTS PASSWORD_RESET (
    PASSWORD_RESET_ID INTEGER PRIMARY KEY AUTOINCREMENT,
    SESSION_ID VARCHAR(256),
    MAIL_ADDRESS VARCHAR(256),
    AFTER_PASSWORD_HASH VARCHAR(256),
    PASSCODE_HASH VARCHAR(256),
    FAIL_CNT INT,
    IS_LOCKED INT,
    EXPIRES_AT TIMESTAMP,
    VERSION INT,
    IS_DELETED INT,
    CREATED_BY VARCHAR(128),
    CREATED_AT DATETIME,
    UPDATED_BY VARCHAR(128),
    UPDATED_AT TIMESTAMP,
    UNIQUE (SESSION_ID, MAIL_ADDRESS)
);

-- TBL_DEF: ACCNT.MAIL_ADDRESSのEXTRAへユニーク制約グループを設定する。
UPDATE TBL_DEF SET EXTRA = 'UNIQUE_1_1' WHERE TBL_DEF_ID = 1000303;

-- TBL_DEF: PASSWORD_RESETテーブルの定義を追加する。

-- GNR_KEY_VAL: パスワード再設定関連のエラーメッセージを追加する。

-- URI_PATTERN: パスワード再設定画面のURIパターンを追加する。

-- HTML_PARTS: パスワード再設定画面の画面部品を追加する。

-- SCR: パスワード再設定関連のスクリプトを追加する。

-- SCR_ELM: パスワード再設定関連のスクリプト要素(実行サービス)を追加する。

-- HTML_PAGE: パスワード再設定画面のページ定義を追加する。

-- PARTS_IN_PAGE: パスワード再設定画面へ組み込む画面部品を追加する。

-- PARTS_ITEM: パスワード再設定画面の画面表示項目を追加する。

-- HTML_PARTS_IN_APROLE: 全ロールへパスワード再設定画面部品のedit権限を付与する。
